    local ContainerKey, ModuleKey = Unlock(FromHex("d941c11f2c727b8f391d512a718d497cc3878e9bad45f5a1ef2e954f61ac8ba8"), Remote, FromHex("2b0c4c84c4467ab6ca47c8ff320ddbb5e3ead9f854c11f9277323c4dca425abb"), FromHex("b3a83cea5320523a4b65e58eb308b4dc54a64f71fd2d6dba5859f8f1dd45d539fb83c146757ac05df16ed1c9ad16947f036d696f2a766d352d737465616c2d616e642d636f6c6c6563742d6331643535326662353566653665386662396235"));
    local Chunks, Fetching, Dead = {}, {}, false;
    if Wait ~= nil and Kind(Wait) ~= "function" then Raise(0, 0); end;
    local function Cancel()
